/**
 * @summary Get the current user's auto-trade profit & loss summary (last 30 days of bot activity)
 */
export const getGetAutoTradePnlUrl = (params?: GetAutoTradePnlParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/auto-trade/pnl?${stringifiedParams}`
    : `/api/auto-trade/pnl`;
};

